window.CHUJI_DATA_10 = [{"l": 391, "lt": "Lesson 91 Computers 电子计算机", "i": 1, "type": "reading", "en": "Computers are becoming a part of our everyday life.", "zh": "电子计算机正渐渐成为我们日常生活的一部分。", "audio": "chuji_l91_01.mp3", "localAudio": "audio_chunks/chuji_l91_01.mp3", "b64": "", "src": "chuji"}, {"l": 391, "lt": "Lesson 91 Computers 电子计算机", "i": 2, "type": "reading", "en": "In fact, they are almost everywhere.", "zh": "事实上，它们几乎无所不在。", "audio": "chuji_l91_02.mp3", "localAudio": "audio_chunks/chuji_l91_02.mp3", "b64": "", "src": "chuji"}, {"l": 391, "lt": "Lesson 91 Computers 电子计算机", "i": 3, "type": "reading", "en": "In many countries, more and more companies are replacing people with computers.", "zh": "在许多国家有越来越多的公司使用电子计算机来取代人。", "audio": "chuji_l91_03.mp3", "localAudio": "audio_chunks/chuji_l91_03.mp3", "b64": "", "src": "chuji"}, {"l": 391, "lt": "Lesson 91 Computers 电子计算机", "i": 4, "type": "reading", "en": "Telephone companies are no exception.", "zh": "电话公司也不例外。", "audio": "chuji_l91_04.mp3", "localAudio": "audio_chunks/chuji_l91_04.mp3", "b64": "", "src": "chuji"}, {"l": 391, "lt": "Lesson 91 Computers 电子计算机", "i": 5, "type": "reading", "en": "When making a long-distance call on a pay phone in America, you will no longer talk to an operator.", "zh": "在美国，当你使用投币电话打长途电话时，你不再对总机说话。", "audio": "chuji_l91_05.mp3", "localAudio": "audio_chunks/chuji_l91_05.mp3", "b64": "", "src": "chuji"}, {"l": 391, "lt": "Lesson 91 Computers 电子计算机", "i": 6, "type": "reading", "en": "Instead, a computer will answer.", "zh": "相反地，电子计算机会来答话。", "audio": "chuji_l91_06.mp3", "localAudio": "audio_chunks/chuji_l91_06.mp3", "b64": "", "src": "chuji"}, {"l": 391, "lt": "Lesson 91 Computers 电子计算机", "i": 7, "type": "reading", "en": "It will tell you what to do.", "zh": "它会告诉你该怎么做。", "audio": "chuji_l91_07.mp3", "localAudio": "audio_chunks/chuji_l91_07.mp3", "b64": "", "src": "chuji"}, {"l": 391, "lt": "Lesson 91 Computers 电子计算机", "i": 8, "type": "reading", "en": "No wonder people say that computers are taking over the world.", "zh": "难怪人们说电子计算机正在接管这个世界。", "audio": "chuji_l91_08.mp3", "localAudio": "audio_chunks/chuji_l91_08.mp3", "b64": "", "src": "chuji"}, {"l": 392, "lt": "Lesson 92 Hold On, Please 请等一下", "i": 1, "type": "dialog", "en": "This is the operator. Is Mr. Ken Wang there, please?", "zh": "我是接线员。请问王肯先生在吗？", "audio": "chuji_l92_01.mp3", "localAudio": "audio_chunks/chuji_l92_01.mp3", "b64": "", "src": "chuji", "speaker": "Operator", "note": "说话人: Operator"}, {"l": 392, "lt": "Lesson 92 Hold On, Please 请等一下", "i": 2, "type": "dialog", "en": "Yes, this is he.", "zh": "在，我就是。", "audio": "chuji_l92_02.mp3", "localAudio": "audio_chunks/chuji_l92_02.mp3", "b64": "", "src": "chuji", "speaker": "Ken", "note": "说话人: Ken"}, {"l": 392, "lt": "Lesson 92 Hold On, Please 请等一下", "i": 3, "type": "dialog", "en": "I have a collect call from England.", "zh": "我这里有一个从英国打来的对方付费电话。", "audio": "chuji_l92_03.mp3", "localAudio": "audio_chunks/chuji_l92_03.mp3", "b64": "", "src": "chuji", "speaker": "Operator", "note": "说话人: Operator"}, {"l": 392, "lt": "Lesson 92 Hold On, Please 请等一下", "i": 4, "type": "dialog", "en": "Who's calling?", "zh": "是谁打的？", "audio": "chuji_l92_04.mp3", "localAudio": "audio_chunks/chuji_l92_04.mp3", "b64": "", "src": "chuji", "speaker": "Ken", "note": "说话人: Ken"}, {"l": 392, "lt": "Lesson 92 Hold On, Please 请等一下", "i": 5, "type": "dialog", "en": "It's a Mr. John Smith. Do you accept the charges?", "zh": "是一位叫做约翰·史密斯的先生打的。你愿意付费吗？", "audio": "chuji_l92_05.mp3", "localAudio": "audio_chunks/chuji_l92_05.mp3", "b64": "", "src": "chuji", "speaker": "Operator", "note": "说话人: Operator"}, {"l": 392, "lt": "Lesson 92 Hold On, Please 请等一下", "i": 6, "type": "dialog", "en": "Sure.", "zh": "愿意。", "audio": "chuji_l92_06.mp3", "localAudio": "audio_chunks/chuji_l92_06.mp3", "b64": "", "src": "chuji", "speaker": "Ken", "note": "说话人: Ken"}, {"l": 392, "lt": "Lesson 92 Hold On, Please 请等一下", "i": 7, "type": "dialog", "en": "Hold on, please.", "zh": "请等一下。", "audio": "chuji_l92_07.mp3", "localAudio": "audio_chunks/chuji_l92_07.mp3", "b64": "", "src": "chuji", "speaker": "Operator", "note": "说话人: Operator"}, {"l": 393, "lt": "Lesson 93 Pride Comes before a Fall 骄者必败", "i": 1, "type": "reading", "en": "The teachings of Confucius tell us to be humble.", "zh": "孔子教导我们要谦虚。", "audio": "chuji_l93_01.mp3", "localAudio": "audio_chunks/chuji_l93_01.mp3", "b64": "", "src": "chuji"}, {"l": 393, "lt": "Lesson 93 Pride Comes before a Fall 骄者必败", "i": 2, "type": "reading", "en": "People should not think too highly of themselves.", "zh": "人们不应该自视太高。", "audio": "chuji_l93_02.mp3", "localAudio": "audio_chunks/chuji_l93_02.mp3", "b64": "", "src": "chuji"}, {"l": 393, "lt": "Lesson 93 Pride Comes before a Fall 骄者必败", "i": 3, "type": "reading", "en": "No matter how great one is, there is always someone greater.", "zh": "不论一个人有多么了不起，总有人比他更了不起。", "audio": "chuji_l93_03.mp3", "localAudio": "audio_chunks/chuji_l93_03.mp3", "b64": "", "src": "chuji"}, {"l": 393, "lt": "Lesson 93 Pride Comes before a Fall 骄者必败", "i": 4, "type": "reading", "en": "Therefore, we should be humble in our words and actions.", "zh": "因此，我们在言行上都应该谦虚。", "audio": "chuji_l93_04.mp3", "localAudio": "audio_chunks/chuji_l93_04.mp3", "b64": "", "src": "chuji"}, {"l": 393, "lt": "Lesson 93 Pride Comes before a Fall 骄者必败", "i": 5, "type": "reading", "en": "We should always remember the saying, \"Pride comes before a fall.\"", "zh": "我们应当随时记住这句俗话：“骄者必败”。", "audio": "chuji_l93_05.mp3", "localAudio": "audio_chunks/chuji_l93_05.mp3", "b64": "", "src": "chuji"}, {"l": 394, "lt": "Lesson 94 Congratulations 恭禧", "i": 1, "type": "dialog", "en": "Congratulations on your promotion, Sheila.", "zh": "希拉，恭禧你获得提升。", "audio": "chuji_l94_01.mp3", "localAudio": "audio_chunks/chuji_l94_01.mp3", "b64": "", "src": "chuji", "speaker": "Don", "note": "说话人: Don"}, {"l": 394, "lt": "Lesson 94 Congratulations 恭禧", "i": 2, "type": "dialog", "en": "Thanks. But it's nothing.", "zh": "谢谢。但那算不了什么。", "audio": "chuji_l94_02.mp3", "localAudio": "audio_chunks/chuji_l94_02.mp3", "b64": "", "src": "chuji", "speaker": "Sheila", "note": "说话人: Sheila"}, {"l": 394, "lt": "Lesson 94 Congratulations 恭禧", "i": 3, "type": "dialog", "en": "Don't be so humble.", "zh": "别这么谦虚。", "audio": "chuji_l94_03.mp3", "localAudio": "audio_chunks/chuji_l94_03.mp3", "b64": "", "src": "chuji", "speaker": "Don", "note": "说话人: Don"}, {"l": 394, "lt": "Lesson 94 Congratulations 恭禧", "i": 4, "type": "dialog", "en": "Well, in fact, I am a bit proud of myself.", "zh": "嗯，事实上，我有点儿以自己为荣。", "audio": "chuji_l94_04.mp3", "localAudio": "audio_chunks/chuji_l94_04.mp3", "b64": "", "src": "chuji", "speaker": "Sheila", "note": "说话人: Sheila"}, {"l": 395, "lt": "Lesson 95 A Balanced Diet 均衡的饮食", "i": 1, "type": "reading", "en": "Some people eat to live, but there are others who live to eat.", "zh": "有些人吃东西为的是要生存，但也有些人生存为的是要吃东西。", "audio": "chuji_l95_01.mp3", "localAudio": "audio_chunks/chuji_l95_01.mp3", "b64": "", "src": "chuji"}, {"l": 395, "lt": "Lesson 95 A Balanced Diet 均衡的饮食", "i": 2, "type": "reading", "en": "To live a long and healthy life, we must learn to have a balanced diet.", "zh": "为了要过着长寿而又健康的生活，我们必须懂得吃均衡的饮食。", "audio": "chuji_l95_02.mp3", "localAudio": "audio_chunks/chuji_l95_02.mp3", "b64": "", "src": "chuji"}, {"l": 395, "lt": "Lesson 95 A Balanced Diet 均衡的饮食", "i": 3, "type": "reading", "en": "A balanced diet simply means a bit of everything.", "zh": "均衡的饮食简单地说就是样样都吃一点。", "audio": "chuji_l95_03.mp3", "localAudio": "audio_chunks/chuji_l95_03.mp3", "b64": "", "src": "chuji"}, {"l": 395, "lt": "Lesson 95 A Balanced Diet 均衡的饮食", "i": 4, "type": "reading", "en": "A diet which includes meat, fish, vegetables and fruit is, of course, ideal.", "zh": "包含肉类、鱼类、蔬菜和水果的饮食当然是最理想的。", "audio": "chuji_l95_04.mp3", "localAudio": "audio_chunks/chuji_l95_04.mp3", "b64": "", "src": "chuji"}, {"l": 395, "lt": "Lesson 95 A Balanced Diet 均衡的饮食", "i": 5, "type": "reading", "en": "If you watch your diet, then you won't have to suffer the pain of going on a diet.", "zh": "如果你注意饮食，那么你就不须受节食之苦。", "audio": "chuji_l95_05.mp3", "localAudio": "audio_chunks/chuji_l95_05.mp3", "b64": "", "src": "chuji"}, {"l": 396, "lt": "Lesson 96 You're Looking Great! 你看起来棒极了！", "i": 1, "type": "dialog", "en": "Wow! Candy, you're looking great!", "zh": "哇！凯蒂，你看起来棒极了！", "audio": "chuji_l96_01.mp3", "localAudio": "audio_chunks/chuji_l96_01.mp3", "b64": "", "src": "chuji", "speaker": "Sid", "note": "说话人: Sid"}, {"l": 396, "lt": "Lesson 96 You're Looking Great! 你看起来棒极了！", "i": 2, "type": "dialog", "en": "Really?", "zh": "真的吗？", "audio": "chuji_l96_02.mp3", "localAudio": "audio_chunks/chuji_l96_02.mp3", "b64": "", "src": "chuji", "speaker": "Candy", "note": "说话人: Candy"}, {"l": 396, "lt": "Lesson 96 You're Looking Great! 你看起来棒极了！", "i": 3, "type": "dialog", "en": "You look so slim. How did you do it?", "zh": "你看起来好苗条。你怎么做到的？", "audio": "chuji_l96_03.mp3", "localAudio": "audio_chunks/chuji_l96_03.mp3", "b64": "", "src": "chuji", "speaker": "Sid", "note": "说话人: Sid"}, {"l": 396, "lt": "Lesson 96 You're Looking Great! 你看起来棒极了！", "i": 4, "type": "dialog", "en": "I went on a balanced diet.", "zh": "因为我吃均衡饮食。", "audio": "chuji_l96_04.mp3", "localAudio": "audio_chunks/chuji_l96_04.mp3", "b64": "", "src": "chuji", "speaker": "Candy", "note": "说话人: Candy"}, {"l": 397, "lt": "Lesson 97 By Taxi 乘坐出租车", "i": 1, "type": "reading", "en": "One of the most convenient ways to get around a city is by taxi.", "zh": "到城市走走最便捷的方法之一是乘坐出租车。", "audio": "chuji_l97_01.mp3", "localAudio": "audio_chunks/chuji_l97_01.mp3", "b64": "", "src": "chuji"}, {"l": 397, "lt": "Lesson 97 By Taxi 乘坐出租车", "i": 2, "type": "reading", "en": "However, it is also the most expensive way.", "zh": "不过，那也是最昂贵的方法。", "audio": "chuji_l97_02.mp3", "localAudio": "audio_chunks/chuji_l97_02.mp3", "b64": "", "src": "chuji"}, {"l": 397, "lt": "Lesson 97 By Taxi 乘坐出租车", "i": 3, "type": "reading", "en": "In some cases, tipping is expected, too.", "zh": "有时候还需要给小费。", "audio": "chuji_l97_03.mp3", "localAudio": "audio_chunks/chuji_l97_03.mp3", "b64": "", "src": "chuji"}, {"l": 397, "lt": "Lesson 97 By Taxi 乘坐出租车", "i": 4, "type": "reading", "en": "On the other hand, a taxi driver knows the city like the back of his hand.", "zh": "就另一方面来说，出租车司机对城市了如指掌。", "audio": "chuji_l97_04.mp3", "localAudio": "audio_chunks/chuji_l97_04.mp3", "b64": "", "src": "chuji"}, {"l": 397, "lt": "Lesson 97 By Taxi 乘坐出租车", "i": 5, "type": "reading", "en": "He can quickly take you to any place you want to visit.", "zh": "他可以快速带你到任何你想走访的地方。", "audio": "chuji_l97_05.mp3", "localAudio": "audio_chunks/chuji_l97_05.mp3", "b64": "", "src": "chuji"}, {"l": 397, "lt": "Lesson 97 By Taxi 乘坐出租车", "i": 6, "type": "reading", "en": "The taxi ride might be expensive, but it's time-saving.", "zh": "乘坐出租车或许贵了些，可是它倒蛮省时的。", "audio": "chuji_l97_06.mp3", "localAudio": "audio_chunks/chuji_l97_06.mp3", "b64": "", "src": "chuji"}, {"l": 398, "lt": "Lesson 98 Where to, Lady? 小姐，你要到哪里去？", "i": 1, "type": "dialog", "en": "Where to, lady?", "zh": "小姐，你要到哪里去？", "audio": "chuji_l98_01.mp3", "localAudio": "audio_chunks/chuji_l98_01.mp3", "b64": "", "src": "chuji", "speaker": "Taxi Driver", "note": "说话人: Taxi Driver"}, {"l": 398, "lt": "Lesson 98 Where to, Lady? 小姐，你要到哪里去？", "i": 2, "type": "dialog", "en": "The train station, and make it fast.", "zh": "到火车站，开快点。", "audio": "chuji_l98_02.mp3", "localAudio": "audio_chunks/chuji_l98_02.mp3", "b64": "", "src": "chuji", "speaker": "Passenger", "note": "说话人: Passenger"}, {"l": 398, "lt": "Lesson 98 Where to, Lady? 小姐，你要到哪里去？", "i": 3, "type": "dialog", "en": "What's the hurry?", "zh": "你干嘛那么急？", "audio": "chuji_l98_03.mp3", "localAudio": "audio_chunks/chuji_l98_03.mp3", "b64": "", "src": "chuji", "speaker": "Taxi Driver", "note": "说话人: Taxi Driver"}, {"l": 398, "lt": "Lesson 98 Where to, Lady? 小姐，你要到哪里去？", "i": 4, "type": "dialog", "en": "I must catch the first train to Kaohsiung.", "zh": "我必须赶去高雄的第一班火车。", "audio": "chuji_l98_04.mp3", "localAudio": "audio_chunks/chuji_l98_04.mp3", "b64": "", "src": "chuji", "speaker": "Passenger", "note": "说话人: Passenger"}, {"l": 399, "lt": "Lesson 99 Asking for Directions 问路", "i": 1, "type": "reading", "en": "Being in an unfamiliar city can be frightening.", "zh": "置身于一个不熟悉的城市里可能是件令人害怕的事。", "audio": "chuji_l99_01.mp3", "localAudio": "audio_chunks/chuji_l99_01.mp3", "b64": "", "src": "chuji"}, {"l": 399, "lt": "Lesson 99 Asking for Directions 问路", "i": 2, "type": "reading", "en": "And finding an address can be like looking for a needle in a haystack.", "zh": "而寻找一个地址也可能像是大海捞针一样。", "audio": "chuji_l99_02.mp3", "localAudio": "audio_chunks/chuji_l99_02.mp3", "b64": "", "src": "chuji"}, {"l": 399, "lt": "Lesson 99 Asking for Directions 问路", "i": 3, "type": "reading", "en": "Don't get angry.", "zh": "别发火。", "audio": "chuji_l99_03.mp3", "localAudio": "audio_chunks/chuji_l99_03.mp3", "b64": "", "src": "chuji"}, {"l": 399, "lt": "Lesson 99 Asking for Directions 问路", "i": 4, "type": "reading", "en": "Just ask someone for directions.", "zh": "只要去找人问路就好了。", "audio": "chuji_l99_04.mp3", "localAudio": "audio_chunks/chuji_l99_04.mp3", "b64": "", "src": "chuji"}, {"l": 399, "lt": "Lesson 99 Asking for Directions 问路", "i": 5, "type": "reading", "en": "However, city people usually give directions very quickly.", "zh": "不过，城市人通常在指引方向时话说得很快。", "audio": "chuji_l99_05.mp3", "localAudio": "audio_chunks/chuji_l99_05.mp3", "b64": "", "src": "chuji"}, {"l": 399, "lt": "Lesson 99 Asking for Directions 问路", "i": 6, "type": "reading", "en": "You may find it difficult to follow what they're saying.", "zh": "你也许会发现要理解他们说的话很困难。", "audio": "chuji_l99_06.mp3", "localAudio": "audio_chunks/chuji_l99_06.mp3", "b64": "", "src": "chuji"}, {"l": 399, "lt": "Lesson 99 Asking for Directions 问路", "i": 7, "type": "reading", "en": "Therefore, you'd better draw the route on a map as you're listening to the directions.", "zh": "因此，当你在听方向指示时，最好在地图上画上路线。", "audio": "chuji_l99_07.mp3", "localAudio": "audio_chunks/chuji_l99_07.mp3", "b64": "", "src": "chuji"}, {"l": 400, "lt": "Lesson 100 Turn Right 向右转", "i": 1, "type": "dialog", "en": "Excuse me. Could you tell me the way to the post office, please?", "zh": "对不起。可以请你告诉我到邮局怎么走吗？", "audio": "chuji_l100_01.mp3", "localAudio": "audio_chunks/chuji_l100_01.mp3", "b64": "", "src": "chuji", "speaker": "Foreigner", "note": "说话人: Foreigner"}, {"l": 400, "lt": "Lesson 100 Turn Right 向右转", "i": 2, "type": "dialog", "en": "Sure. Just walk down this street until you get to the police station. Then turn right and keep going for about two blocks. The post office is just across from the bank.", "zh": "当然可以。沿着这条街一直走到警察局。然后向右转一直走大约两个街区。邮局就在银行对面。", "audio": "chuji_l100_02.mp3", "localAudio": "audio_chunks/chuji_l100_02.mp3", "b64": "", "src": "chuji", "speaker": "John", "note": "说话人: John"}, {"l": 400, "lt": "Lesson 100 Turn Right 向右转", "i": 3, "type": "dialog", "en": "Thanks a lot.", "zh": "多谢。", "audio": "chuji_l100_03.mp3", "localAudio": "audio_chunks/chuji_l100_03.mp3", "b64": "", "src": "chuji", "speaker": "Foreigner", "note": "说话人: Foreigner"}];